"""Author the eight Covenant NPC assets. Original four supplied skins are untouched."""
from pathlib import Path
import json
P=Path(__file__).resolve().parents[1]
R=P/'src/main/resources/assets/thedeepnightnpcs'
# id, title, coat, trim, skin, hair, personal greeting, craft/life topic
people=[
('rowan','Keeper of Dawnstead',0x49604c,0xc8ab6d,0xd5a37e,0x5b3729,"A refuge begins with a light in the window, but it survives because someone tends the stores. I am Rowan. Eldara carries the main chronicle; bring me the work that makes Dawnstead a home.","A town hall is a promise to remember the living. Help the builders, keep a reserve of food, and leave room at the table for the next arrival. My colony and stewardship requests are practical work, and the relief deliveries always need another pair of hands."),
('sera','Keeper of the Uncensored Library',0x454979,0xc5b786,0xb98768,0x252331,"Sera, archivist. You may disagree with a book here, including one I wrote. Eldara holds the main expedition reports. I have research, spellcraft, and recovered histories that need a patient witness.","The old college treated knowledge as a privilege. We keep the door open and the margins wide. Bring me your annotations, your difficult relics, and the evidence that refuses to fit the official story. A question is a better beginning than an oath of obedience."),
('mara','Hearthwright of Dawnstead',0x884d31,0xc69a55,0xa96948,0x30201a,"If that tool is broken, set it on the bench. If it is not, you can help mend someone else's. I am Mara. Eldara will brief you on the wider campaign; I need hands for the workshop and supplies for the apprentices.","A forge that makes only swords will never rebuild a province. We teach hinges, ploughs, sound roofs, and armor that brings its wearer home. Every apprentice earns a mark of their own. Speak to me about the work of many hands, and the name an apprentice is ready to put on it."),
('elian','Captain of the Free Watch',0x586771,0xcbb57c,0xc49172,0x494039,"Elian, Free Watch. You need not salute. Eldara coordinates the main campaign; I keep the watch's requests and the recovered Deep Night ledger. We clear roads so people can use them, then we come home.","A good order can survive a question. I learned that too late for some of my regiment. The new watch keeps blankets beside its weapons and counts the living before counting victories. Its charter, its border work, and the reports I once refused to finish are here when you are ready."),
('iona','Scout of the Far Lanterns',0x365d54,0xb79c62,0xbd835d,0x392922,"You found the road back. That is the part I care about. I am Iona. Eldara has the main chronicle; my maps, ranger work, and unfinished journeys could use another traveler who knows when to turn around.","I draw safe returns before destinations. Some paths need a lantern; others need to stay undisturbed. The atlas belongs to the next scout as much as it belongs to me. Ask about my maps, and I may finally tell you about the valley I left blank."),
('tamsin','Healer of the Living Garden',0xd6d0b2,0x557761,0xe0b693,0x875132,"Sit for a moment. A journey is allowed to begin with rest. I am Tamsin. Eldara gives the main assignments; I look after the dispensary, the garden, and the people who come back from them.","I label the bottles because hope is no substitute for knowing what is inside. We need clean glass, food, seedlings, and people willing to learn. The garden should outlive my own working hands. When the stores are full, remind me that a healer is allowed an afternoon off."),
('fen','Boatkeeper of the Common Harbor',0x36516b,0xd2bc89,0x976b4e,0x282724,"Fen, boatkeeper. There is room aboard if you need passage, and there is work if you can spare the time. Eldara has the main expedition orders; the harbor's requests come through me.","A good fleet has spare provisions, repairable hulls, and no captain too proud to return before a storm. I keep the coastal routes, relief boats, and common pantry moving. We name no flagship here. Every vessel has to bring its whole crew home."),
('ysolde','Warden of the Covenant of Wings',0x694757,0xc3a36e,0xd1a587,0xddd1b9,"Ysolde. Keep your bow lowered until you know which creature you are looking at. Eldara brings the main campaign reports; I keep the dragon fellowship and the requests that begin where an ordinary map ends.","Not every wing casts an enemy's shadow. Read the account, prepare the nursery, and learn a creature's habits before approaching. I once kept only a hunting ledger. The newer book has feed budgets and observations in it, and I am prouder of that one."),
]
langpath=R/'lang/en_us.json';lang=json.loads(langpath.read_text(encoding='utf-8-sig'))
java=['package dev.thedeepnightnpcs;','', 'import java.util.List;', '', 'public final class NpcRoster {', '    public record Companion(String id,String title,int coat,int trim) {}', '    public static final List<Companion> COMPANIONS=List.of(']
for i,(name,title,coat,trim,face,hair,greeting,work) in enumerate(people):
    java.append(f'        new Companion("{name}","{title}",0x{coat:06x},0x{trim:06x})'+(',' if i<len(people)-1 else ''))
    lang[f'entity.thedeepnightnpcs.{name}']=name.title();lang[f'item.thedeepnightnpcs.{name}_spawn_egg']=name.title()+' Spawn Egg'
    (R/f'models/item/{name}_spawn_egg.json').write_text(json.dumps({'parent':'minecraft:item/template_spawn_egg'},indent=2))
    nodes={'root':{'title':title,'text':greeting,'children':['work','quests','eldara']},'work':{'title':'Your work','text':work},'quests':{'title':'How can I help?','text':"Choose Covenant quests in our opening conversation to see my assignments. Accept one here before setting out, then return to me to turn it in and receive your emeralds. Use the minus key (-) to track its objectives while traveling. Some requests follow earlier work; your journal explains what must be finished first. If the Ashen Covenant quest mod is absent, I can still talk, but cannot offer its quests."},'eldara':{'title':'The main chronicle','text':"Speak to Eldara and choose Main quests to continue the three books of the Ashen Covenant. She receives the expedition reports and gives the next main assignment. The rest of us have our own work, and we will ask for it in person."}}
    (R/f'dialogue/{name}.json').write_text(json.dumps(nodes,indent=2),encoding='utf-8')
    # The character skins are supplied by the user; never regenerate or alter them.
    source=P.parent/'thedeepnightnpcs'/f'{name}.png'
    destination=R/f'textures/entity/{name}.png'
    if source.exists(): destination.write_bytes(source.read_bytes())
    elif not destination.exists(): raise FileNotFoundError(f'User-supplied skin required: {name}.png')
java+=['    );','    public static String name(String kind) { return kind.equals("spire_guard") ? "Spire Guard" : Character.toUpperCase(kind.charAt(0))+kind.substring(1); }','    public static String title(String kind) {','        return switch(kind) {','            case "eldara" -> "The Eternal Sage"; case "caelen" -> "The Monster Hunter";','            case "jorge" -> "The Armskeeper"; case "spire_guard" -> "Spire Watch";','            default -> COMPANIONS.stream().filter(c -> c.id().equals(kind)).map(Companion::title).findFirst().orElse("The Covenant");','        };','    }','}']
(P/'src/main/java/dev/thedeepnightnpcs/NpcRoster.java').write_text('\n'.join(java)+'\n',encoding='utf-8');langpath.write_text(json.dumps(lang,indent=2),encoding='utf-8')
print('Created eight NPC identities, dialogues and eggs; preserved user-supplied skins.')
